import test from 'node:test';
import assert from 'node:assert/strict';
import * as A from '../src/astronomy.mjs';
import * as P from '../src/projection.mjs';
const near=(a,b,t=1e-9)=>assert.ok(Math.abs(a-b)<t,`${a} != ${b} tolerance ${t}`);
test('J2000 UTC Julian day',()=>near(A.julianDate(Date.UTC(2000,0,1,12)),2451545));
test('Greenwich mean sidereal J2000 anchor',()=>near(A.gmstDeg(2451545),280.46061837,1e-7));
test('UTC instant must be explicit numeric or Date, never ambiguous civil text',()=>{for(const x of [null,'2026-01-01',NaN,Infinity])assert.throws(()=>A.julianDate(x));});
test('equatorial transit is zenith at equator',()=>near(A.equatorialToHorizontal(20,0,20,0).altDeg,90,1e-6));
test('rising east and setting west have correct signs',()=>{near(A.equatorialToHorizontal(90,0,0,0).azDeg,90);near(A.equatorialToHorizontal(270,0,0,0).azDeg,270);});
test('north pole height equals latitude',()=>{for(const lat of [-89,-30,0,24.47,28.54,64.15,90])near(A.equatorialToHorizontal(0,90,100,lat).altDeg,lat,1e-6);});
test('all observer poles and zeniths remain finite',()=>{for(const lat of [-90,0,90])for(const dec of [-90,0,90])for(const ra of [0,90,180,359.999]){const h=A.equatorialToHorizontal(ra,dec,0,lat);assert.ok(Number.isFinite(h.azDeg)&&Number.isFinite(h.altDeg));}});
test('reject invalid terrestrial latitude',()=>{for(const lat of [null,NaN,91,-91,'28'])assert.throws(()=>A.equatorialToHorizontal(0,0,0,lat));});
test('precession at J2000 is identity',()=>{const v=A.radecVector(101.287,-16.716);const w=A.precessJ2000(v,2451545);v.forEach((x,i)=>near(x,w[i]));});
test('precession changes zero RA to positive RA and declination after J2000',()=>{const p=A.vectorRaDec(A.precessJ2000([1,0,0],2451545+36525));assert.ok(p.raDeg>1&&p.raDeg<1.4&&p.decDeg>.5&&p.decDeg<.6);});
test('proper motion uses mu_alpha*cos(delta) and is stable at poles',()=>{const s={raDeg:0,decDeg:60,epochJyear:2000,pmRaCosDecMasYr:1000,pmDecMasYr:0};const p=A.vectorRaDec(A.propagateJ2000(s,2001));near(p.raDeg*3600,2,1e-4);const pole=A.propagateJ2000({...s,decDeg:90},2001);assert.ok(pole.every(Number.isFinite));});
test('unknown proper motion is flagged, not claimed zero measurement',()=>{const o=A.observeStar({hip:11767,raDeg:37.946,decDeg:89.264,epochJyear:2000,pmRaCosDecMasYr:null,pmDecMasYr:null},{utcMs:Date.UTC(2026,9,4),latDeg:28.54,lonDeg:-81.38});assert.ok(o.warnings.includes('proper-motion-unavailable'));assert.ok(o.altDeg>27&&o.altDeg<30);});
test('location longitude acts east-positive',()=>{const s={hip:1,raDeg:0,decDeg:0,epochJyear:2000};const o={utcMs:Date.UTC(2026,0,1),latDeg:20,lonDeg:0};const a=A.observeStar(s,o),b=A.observeStar(s,{...o,lonDeg:90});assert.ok(Math.abs(a.altDeg-b.altDeg)>20);});
test('time changes even when scene identity does not',()=>{const s={hip:1,raDeg:0,decDeg:0,epochJyear:2000};const o={utcMs:Date.UTC(2026,0,1),latDeg:20,lonDeg:0};assert.ok(Math.abs(A.observeStar(s,o).altDeg-A.observeStar(s,{...o,utcMs:o.utcMs+3600000}).altDeg)>1);});
test('refraction is optional and cannot be used outside model domain',()=>{near(A.refractionDeg(20,0,10),0);assert.ok(A.refractionDeg(0,1010,10)>.4);near(A.refractionDeg(90,1010,10),0);assert.throws(()=>A.refractionDeg(-5,1010,10));});
test('azimuthal projection round trips cardinal and intermediate directions',()=>{for(const alt of [0,10,45,89.9,90])for(const az of [0,90,180,270,357]){const p=P.projectAllSky({altDeg:alt,azDeg:az},{width:400,height:400});const q=P.unprojectAllSky(p.x,p.y,{width:400,height:400});near(q.altDeg,alt,1e-6);if(alt<90)near(q.azDeg,az,1e-6);}});
test('legacy widget dome has precisely documented axes',()=>{const n=P.projectWidgetDome({altDeg:0,azDeg:0});near(n.x,162);near(n.y,186);const e=P.projectWidgetDome({altDeg:0,azDeg:90});near(e.x,-108);near(e.y,-30);});
test('perspective camera looks along its specified azimuth and altitude',()=>{const p=P.projectPerspective({altDeg:30,azDeg:90},{width:325,height:530,azDeg:90,altDeg:30,fovYDeg:90});near(p.x,162.5);near(p.y,265);assert.equal(P.projectPerspective({altDeg:-30,azDeg:270},{width:325,height:530,azDeg:90,altDeg:30,fovYDeg:90}),null);});
test('slerp crosses RA wrap locally rather than traversing the whole sky',()=>{const a=A.radecVector(359,0),b=A.radecVector(1,0);const m=A.vectorRaDec(A.slerp(a,b,.5));assert.ok(m.raDeg<1e-8||m.raDeg>359.99999);});
test('angular separation accepts differently scaled finite direction vectors',()=>near(A.angularSeparation([100,0,0],[2,2,0]),45));
